components.customCss:
.card-container {
    display: grid;
    /* Creates a responsive grid: minimum width of 300px per card,
       and expands to fill available space (1fr) */
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 20px; /* Space between the cards */
    padding: 20px;
    max-width: 1200px;
    margin: 0 auto; /* Centers the container on the page */
}

.card {
    border: 1px solid #ddd;
    border-radius: 8px;
    box-shadow: 0 4px 8px rgba(0,0,0,0.1);
    overflow: hidden; /* Ensures image corners are rounded */
    background-color: #fff;
    display: flex;
    flex-direction: column;
    height: 100%; /* Ensures all cards have the same height */
}

.card img {
    width: 100%;
    height: 200px; /* Fixed height for images, adjust as needed */
    object-fit: cover; /* Ensures the image covers the area without distortion */
}

.card-content {
    padding: 15px;
    display: flex;
    flex-direction: column;
    flex-grow: 1; /* Allows content to expand to fill remaining space */
}

.card-content h3 {
    margin-top: 0;
    font-size: 1.25rem;
}

.card-content p {
    margin-bottom: 15px;
    flex-grow: 1; /* Allows paragraph to expand */
}

.card-content a {
    display: inline-block;
    background-color: #007bff;
    color: white;
    padding: 10px 15px;
    text-decoration: none;
    border-radius: 4px;
    text-align: center;
    margin-top: auto; /* Pushes the link to the bottom */
}

